from pathlib import Path
import re, html, hashlib
root=Path(__file__).resolve().parents[2]
page=root/'chapters/ch24.html'
base=(root/'docs/reviews/ch22-ch23-ch24-baseline/ch24.html').read_text()
assert hashlib.sha256(page.read_bytes()).hexdigest()=='02baee6d4bbdb49fb5c84d74367d14c790b692eb849ac424febe7de1641d12c4', 'target changed: inspect before writing'
decks=re.findall(r'<figure class="deck">[\s\S]*?</figure>',base)
assert len(decks)==6

def lang(z,e): return f'<span class="lang-zh">{z}</span><span class="lang-en">{e}</span>'
def bi(z,e,cls=''):
    attr=f' class="{cls}"' if cls else ''
    return f'<div class="bilingual"><div class="lang-zh"><p{attr}>{z}</p></div><div class="lang-en"><p{attr}>{e}</p></div></div>\n'
def h(z,e,n=2): return f'<h{n}>{lang(z,e)}</h{n}>\n'
def code(file,label,kind='pseudocode'):
    text=(root/'examples/ch24'/file).read_text().rstrip('\n')
    return f'<pre data-language="{label}" data-kind="{kind}" data-source="{file}"><code>{html.escape(text,quote=True)}</code></pre>\n'
def table(headers,rows):
    return '<table><thead><tr>'+''.join('<th>'+lang(*x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+lang(*x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>\n'
urls={
1:'https://docs.stripe.com/api/idempotent_requests',
2:'https://docs.stripe.com/error-low-level',
3:'https://docs.stripe.com/webhooks',
4:'https://docs.stripe.com/currencies',
5:'https://docs.stripe.com/refunds',
6:'https://www.postgresql.org/docs/18/ddl-constraints.html',
7:'https://docs.adyen.com/reporting/settlement-reconciliation/transaction-level/settlement-details-report/',
8:'https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html',
9:'https://docs.tigerbeetle.com/coding/financial-accounting/',
10:'https://www.postgresql.org/docs/18/runtime-config-wal.html'}
def ref(n):return f'<a href="{urls[n]}" target="_blank" rel="noopener">[{n}]</a>'
def cap(d,i,z,e):
    frames=list(re.finditer(r'<figcaption>[\s\S]*?</figcaption>',decks[d]))
    m=frames[i];decks[d]=decks[d][:m.start()]+'<figcaption>'+lang(z,e)+'</figcaption>'+decks[d][m.end():]

# Keep all 6 decks / 30 frame IDs and geometry. Correct only local semantics.
decks[1]=decks[1].replace('>send a7</text>','>persist SENT</text>')
decks[1]=decks[1].replace('CREATED is a durable attempt. Sending its channel command moves it to SENT.','CREATED is a durable attempt. Persist SENT before I/O; it means a7 may leave, not that the PSP received it.')
decks[3]=decks[3].replace('dedupe pay_no','dedupe event_id').replace('Order deduplicates pay_no','Order deduplicates the stable payment.paid event ID')
cap(0,0,'第1帧先画受理骨架；第2帧补齐同一 T1 的渠道命令，才是完整实现。202 只表示持久受理，不表示渠道已收款。','Frame 1 sketches acceptance; frame 2 completes the same T1 with its channel command. Only that full transaction is the implementation. 202 means durable acceptance, not captured funds.')
cap(1,0,'SENT 在外部 I/O 前持久化，表示 a7 可能送出。worker 可能随后崩溃，所以 SENT 既不证明渠道收到，也不证明已扣款。','Persist SENT before external I/O: a7 may leave. The worker may crash next, so SENT proves neither provider receipt nor capture.')
cap(1,2,'Resolver 查原对象；只有渠道重试期限和发送边界都可保证时才重放同一 a7。0.1% 未决是教学假设，即每天 1,000 笔，年龄只触发核查。','Resolver queries the original object. Replay a7 only when both provider window and send bounds are guaranteed. Assumed 0.1% uncertainty is 1,000/day; age triggers investigation.')
cap(2,4,'inbox 去重交付，Posting gate 是同库事务里的金额效果 UNIQUE。图内 PSP + account 省略了固定环境；实现还含 environment。每个退款有独立对象与 kind。','Inbox deduplicates delivery; Posting gate denotes the effect UNIQUE in the local transaction. PSP + account omits the fixed environment on the board; implementation includes it. Refunds have separate objects and kind.')
cap(3,3,'Order 按稳定 event_id 去重并持久应用自己的状态机后 ACK。同一 payment.paid 重投不重扣；退款通知使用另一种事件与身份。','Order deduplicates the stable event_id and durably applies its state machine before ACK. Replaying payment.paid never recharges; refund notifications have their own event kind and identity.')
cap(4,4,'后来确认 r1 成功，Posting 同事务追加退款分录并结转预留：已退从 3,000 变 5,000，预留从 2,000 变 0，余量仍 5,000。上方数值是转换前。','Later verified r1 success atomically appends its journal and converts reservation: refunded 3,000→5,000, reserved 2,000→0, still 5,000 available. The upper figures show the state before conversion.')

parts=[]
parts.append('<section class="goal">'+h('本章核心：保存意图、承认未知、按效果记账','Core: preserve intent, retain uncertainty, post each effect'))
parts.append(bi('你要能回答三个问题：同一请求、同一付款尝试、同一金额效果各由哪个键识别？渠道已经扣款但回复丢失，谁来恢复？账本、退款额度与通知各在哪个提交点成立？','Answer three questions: which keys identify a request, a payment attempt, and a financial effect? Who recovers a lost reply after a charge? At which commits do the journal, refund capacity, and notifications become valid?'))
parts.append(bi('主线是 <strong>payment 意图 → attempt a7 → 渠道证据 → Posting → Order</strong>。保留六组演进图；每组附近给出关键实现和崩溃后的恢复记录。','Follow <strong>payment intent → attempt a7 → provider evidence → Posting → Order</strong>. Six existing decks remain, with the implementation and crash-recovery records beside each mechanism.'))
parts.append('</section>\n<section>'+h('先定义三种成功与规模','Define three successes and scale'))
parts.append(bi('我设计商户收款：PSP 托管页面、单币种 CNY、一次完整 capture、可多次部分退款。先持久受理，再调用渠道；超时保留 UNKNOWN。验真结果通过同一 Posting 门写账，入账后用 Outbox 通知订单，最后用查询与结算对账收口。','Design merchant pay-in: PSP-hosted collection, CNY, one full capture, and multiple partial refunds. Persist acceptance before calling the provider, retain UNKNOWN on timeout, route verified results through one Posting gate, notify orders through outbox, and resolve gaps with queries and settlement reconciliation.','say'))
parts.append(table([('事实','Fact'),('成立条件','Commit/evidence'),('不能推出什么','What it does not prove')],[
[('已受理 · 202 + pay_no','Accepted · 202 + pay_no'),('payment、attempt、渠道命令同库提交','Payment, attempt, channel command commit together'),('外部尚可能未执行','Provider may not have executed')],
[('渠道确认 capture','Provider capture confirmed'),('核对账户、对象、金额、币种的权威证据','Authoritative evidence matching account, object, amount, currency'),('本地账可能仍待入','Local posting may still be pending')],
[('本地已入账','Locally posted'),('完整分录、状态、订单 Outbox 同事务','Complete entries, state, order outbox in one transaction'),('订单可能尚未收到通知','Order may not yet have received notification')]]))
parts.append(bi('规模均为教学假设：每日 1,000,000 创单、70% 成功、每笔成功平均两次回调、峰值十倍；受理 p99 目标 300 ms，渠道等待预算 2 s。钱包双花、换汇、出款与争议处理不展开；<a href="ch18.html">Ch18</a> 负责订单关单竞态。本章的 payment 是本地领域意图，并不等同于某一家 PSP 的同名对象。','All scale values are teaching assumptions: 1,000,000 creates/day, 70% success, two receipts per success, 10× peak, 300 ms local-acceptance p99 target, and 2 s channel wait budget. Wallet double-spend, FX, payouts, and disputes are outside scope; <a href="ch18.html">Ch18</a> owns order-close races. Our payment is a local domain intent, not necessarily a provider object of the same name.'))
parts.append('<details><summary>'+lang('容量复算、耐久性与保留边界','Capacity arithmetic, durability, and retention')+'</summary>\n')
parts.append(bi('创单：1,000,000÷86,400×10≈115.74/s，口播 116；成功收款：700,000÷86,400×10≈81/s；回调接收：1,400,000÷86,400×10≈162/s。三者不是同一个 TPS。先测一套关系库的混合事务预算，再决定分片；将一笔付款的 attempt、journal 和退款放在同一财务分区。','Creates: 1,000,000/86,400×10≈115.74/s, rounded to 116; successful captures: 700,000/86,400×10≈81/s; receipts: 1,400,000/86,400×10≈162/s. These are different rates. Measure mixed transactions on one relational authority before sharding; colocate a payment’s attempts, journal, and refunds in one financial partition.'))
parts.append(bi('假设 worker 预算 500 receipts/s，停十分钟的工作量上界 162×600=97,200；仍有新流量时净消化 500−162=338/s，约 288 秒追平。inbox 去重后可能更少，但查询与锁争用也可能降低预算。假设 0.1% 创单未决，则每日 1,000 笔；跟踪数量、金额、最老年龄，年龄不自动生成失败。','At an assumed 500 receipts/s worker budget, ten minutes yields at most 162×600=97,200 work items. With ongoing arrivals, spare capacity is 338/s and drain time about 288 s. Inbox dedupe can reduce work, while queries and locks can lower capacity. Assumed 0.1% uncertain creates means 1,000/day; track count, amount, and oldest age without turning age into failure.'))
parts.append(bi('十进制存储估算：支付行 1 KB、每条分录 200 B、每次接收审计 1 KB，一年分别是 365 GB、102.2 GB、511 GB；合计 978.2 GB，三份 2.9346 TB。这里只算三类原始行，不含 attempt、索引、WAL、备份、退款和更长保留。511 GB 是逐投递审计上界，不是去重 inbox 的行量；365 天只是容量假设。','With decimal units, a 1 KB payment, 200 B entry, and 1 KB per-delivery audit yield 365 GB, 102.2 GB, and 511 GB/year; total 978.2 GB, or 2.9346 TB for three copies. This excludes attempts, indexes, WAL, backups, refunds, and longer retention. 511 GB bounds delivery audits, not deduplicated inbox rows; 365 days is only a planning assumption.'))
parts.append(bi('24 h 只作为本地响应缓存假设。请求身份或拒绝旧键的墓碑、payment、未决 attempt 与财务效果键必须覆盖业务重试与审计边界，不能随缓存清空而重新扣款。过期请求先查询或拒绝；换 header 仍回到同一业务意图。','24 h is only a local response-cache assumption. Request identities or old-key rejection tombstones, payments, uncertain attempts, and effect keys must cover business retry/audit boundaries; cache expiry cannot authorize another charge. Expired requests query or reject, while changed headers still resolve the same business intent.'))
parts.append(bi('财务 COMMIT 假设本地 WAL 与指定同步副本均持久落盘；PostgreSQL 18 中这依赖 fsync、同步副本配置和 synchronous_commit=on 等具体条件。副本数三并不自动提供该保证，也不等于副本已可查询。切主须排除旧主并只提升具备已确认提交的节点，无法确认时暂停财务写。'+ref(10),'Financial COMMIT assumes durable local WAL and designated synchronous standby flush. In PostgreSQL 18 this requires the corresponding fsync, synchronous-standby, and synchronous_commit=on configuration. Three copies alone do not provide it or guarantee standby query visibility. Fence the old primary and promote only a node carrying acknowledged commits; pause financial writes if that cannot be established. '+ref(10)))
parts.append('</details></section>\n<section>'+h('1 · 先落意图，给每层身份定范围','1 · Persist intent and scope each identity'))
parts.append(bi('<strong>先提交 payment、attempt 与渠道命令，再碰 PSP。</strong> 第1组第2帧的 T1 是本地边界；第3帧才跨出数据库。Pay worker 负责恢复同一 a7，不负责生成新付款。','<strong>Commit payment, attempt, and channel command before touching the PSP.</strong> T1 in deck 1 frame 2 is the local boundary; frame 3 crosses it. Pay worker recovers a7 rather than creating a new payment.'))
parts.append(decks[0])
parts.append(table([('身份','Identity'),('唯一范围','Unique scope'),('重复时的动作','Duplicate behavior')],[
[('业务意图 payment','Business intent'),('environment + merchant + order_ref + 授权业务版本','environment + merchant + order_ref + authorized business version'),('换请求键仍回原 pay_no；版本不能由浏览器任意加一','New header still resolves pay_no; browser cannot invent a version')],
[('API 请求键','API request key'),('environment + merchant + operation + key','environment + merchant + operation + key'),('同摘要回原受理，摘要不同拒绝','Replay acceptance for same digest; reject changed body')],
[('外部尝试 a7','Provider attempt a7'),('environment + channel + account + channel_key','environment + channel + account + channel_key'),('冻结参数；仅在渠道契约内重放','Freeze parameters; replay only under provider contract')],
[('接收/金额效果','Receipt / financial effect'),('event_id 与 capture/refund object + kind 分开','Separate event_id from capture/refund object + kind'),('交付重复与金额重复分别拦截','Deduplicate delivery and money independently')]]))
parts.append(h('让 UNIQUE 仲裁竞争，再比较请求摘要','Let UNIQUE arbitrate races, then compare digests',3))
parts.append(code('keys.sql','SQL · SQLite executable indexes','teaching'))
parts.append(code('create.pseudo','Pseudocode · durable create'))
parts.append(bi('输入来自已鉴权商户，金额由订单服务的不可变报价校验；摘要涵盖订单、金额、币种、支付方式与业务版本。insertOrReadIntent 对应非空 UNIQUE 约束；冲突后回滚整个事务、重新读取赢家并比较摘要，不能在已被 PostgreSQL 唯一冲突中止的事务里继续 SELECT。只重试这两个明确的身份冲突，不能吞掉任意约束错误。'+ref(6),'Authenticate the merchant and validate an immutable order quote. The digest binds order, amount, currency, method, and business version. insertOrReadIntent uses non-null UNIQUE constraints; after conflict, roll back, restart, and compare the winner. A PostgreSQL transaction aborted by a unique violation cannot simply continue with SELECT. Retry only these identified identity conflicts, not arbitrary constraint errors. '+ref(6)))
parts.append(bi('响应丢失用同键解析原提交；缓存过期也不抹掉业务意图。这里没有“换 key 就换一笔钱”的入口。Outbox 把本地意图与命令绑在 T1 内，PSP 副作用仍在外面；relay 或 worker 重做，仍需渠道幂等契约。同步调用也可选，但仍先保存 attempt，并承担渠道尾延迟。'+ref(8),'Resolve a lost acceptance reply through the same identity. Cache expiry never erases the intent, and a new key cannot authorize another payment. Outbox binds local intent and command in T1; PSP effects remain outside it, requiring the provider contract on repeats. Synchronous calling is an alternative only after persisting the attempt and accepting provider tail latency. '+ref(8)))
parts.append('</section>\n<section>'+h('2 · UNKNOWN 是知识状态，不是扣款失败','2 · UNKNOWN is uncertainty, not a failed charge'))
parts.append(bi('<strong>先持久化 SENT，再做 I/O；迟到超时只能更新仍未决的尝试。</strong> 第2组画状态转换，不能把箭头当渠道执行顺序。成功证据走 Posting；浏览器跳转页没有财务状态转换权限。','<strong>Persist SENT before I/O; a late timeout may update only an unresolved attempt.</strong> Deck 2 shows knowledge transitions, not provider execution order. Successful evidence enters Posting; browser redirects cannot authorize financial transitions.'))
parts.append(decks[1])
parts.append(code('dispatch.pseudo','Pseudocode · dispatch and monotone result merge'))
parts.append(bi('firstSendAt 与 retryBefore 只设置一次，不被重试延长。示例把 pending、网络中断与不可判定 5xx 留在 UNKNOWN；渠道明确证实不会发生扣款，才映射 DECLINED。并发 webhook 已将 a7 记成 CONFIRMED 时，旧 worker 的超时不能再覆盖为 UNKNOWN；这由锁内状态比较保证，单靠最后写入时间不行。','Set firstSendAt and retryBefore once; retries never extend them. This model keeps pending, disconnections, and ambiguous 5xx as UNKNOWN; DECLINED requires proof of no charge and no future execution. If a concurrent webhook already confirmed a7, a stale worker timeout cannot overwrite it. Compare state under the DB lock instead of trusting last-write timestamps.'))
parts.append(bi('本章引用的 <strong>Stripe API v1</strong> 在执行开始后保存首个响应，包括 500，并可在至少 24 h 后清理键。官方错误处理建议只在原请求后的前 24 h 内同键同参数重试，仍未知则停止重放、核实结果。v2 的重放行为和窗口不同，这条规则不外推到 v2 或其他渠道。'+ref(1)+' '+ref(2),'The cited <strong>Stripe API v1</strong> retains the first executed response, including 500, and may prune keys after at least 24 h. Its error guide limits same-key/parameter retries to the first 24 h, then requires reconciliation if unresolved. API v2 has different replay behavior and a different window; do not generalize this v1 rule to v2 or other providers. '+ref(1)+' '+ref(2)))
parts.append(bi('<strong>本地 deadline 不是 PSP 的 fencing。</strong> 发送前检查无法阻止 worker 暂停很久、在途请求延迟后才到渠道。safeReplayWindow 只有在渠道保证、时钟裕量、调度/传输上界都成立时才可用；无法保证时，只查询已绑定对象或留 Review，不自动重放 create。优先使用渠道端不会再次扣款的稳定对象/状态约束，不能宣称本地租约实现了任意故障下的 exactly-once。','<strong>A local deadline does not fence the PSP.</strong> A pre-send check cannot stop a suspended worker or a delayed in-flight request arriving later. safeReplayWindow is conditional on provider guarantees, clock margin, and scheduling/transport bounds. Without those bounds, query the bound object or retain Review rather than automatically replay create. Prefer provider-enforced stable-object/state constraints; a local lease does not establish exactly-once across arbitrary failures.'))
parts.append(bi('Resolver 能拿到对象 ID 就查原对象；create 回复丢失时，只有已验证的商户引用查询、窗口内同键取回结果或已验签回调/账单关联可用。查不到、查询失败或等太久都不是“未扣款”证据。新 attempt 需要单独授权，而且旧对象/命令已不可再执行；不能一边让旧 worker 可能扣款，一边自动切渠道。','Resolver queries the original object when its ID is known. After a lost create reply, use only a verified merchant-reference lookup, valid same-key recovery, or authenticated callback/report correlation. Missing objects, failed queries, and elapsed time do not prove no charge. A new attempt requires separate authorization and a non-executable old command/object; never switch providers while an old sender could still charge.'))
parts.append('</section>\n<section>'+h('3 · Webhook 先持久接收，再处理金额效果','3 · Receive webhooks durably before applying effects'))
parts.append(bi('<strong>ACK 的承诺是已接管，不是已入账。</strong> 第3组先保存事件，再由 Posting 按 capture/refund 身份去重。签名有效仍要核对象、账户与金额，不能把任意 success 字段当付款事实。','<strong>ACK promises durable responsibility, not posting.</strong> Deck 3 saves events before Posting deduplicates capture/refund effects. A valid signature still requires object, account, and amount validation; a success field alone is insufficient.'))
parts.append(decks[2])
parts.append(code('webhook.pseudo','Pseudocode · authenticated durable inbox'))
parts.append(bi('endpointConfig 的环境、账户与 secret 来自服务端配置，不信任 body 自选身份。验证原始 body 后，inbox 提交才 2xx；数据库提交未知可以报可重试错误，让同一 event 重投。签名库和时间容差依渠道选定，本章不自造通用验签算法。Stripe 文档支持原始 body 验签、异步处理以及重复/乱序交付；durable inbox 是本章的设计选择。'+ref(3),'Server endpoint configuration supplies environment, account, and secret. Verify the raw body, commit inbox, then return 2xx. An unknown DB commit may return a retryable error and accept event redelivery. Use the provider SDK/tolerance contract, not an invented universal signature scheme. Stripe documents raw-body verification, asynchronous processing, duplicates, and unordered delivery; durable inbox is our design choice. '+ref(3)))
parts.append(bi('租约只负责重新领取工作；失效 worker 可能仍在执行，金额正确性靠 Posting UNIQUE 与本地事务。相同 event_id 重投不重建工作；不同 evt_9 仍可能指向相同 capture c9。金额效果冲突须比较原 payment、attempt/refund、金额和币种；不能把所有 UNIQUE 冲突都当成功。','Leases recover work claims; expired workers may still execute, so Posting uniqueness and transactions protect money. Redelivery of one event does not recreate work, while evt_9 may still describe capture c9. Effect conflicts must compare the original payment, attempt/refund, amount, and currency rather than treating every UNIQUE conflict as success.'))
parts.append(bi('received_at 与秒级 created 不能恢复严格业务顺序。退款事件先到而本地 capture 未入账时，先留待关联并查对象；旧处理中/失败通知晚到也不能降回已确认成功。提供商重试窗口有限，最终仍可能缺事件，因此保留扫描、持久异常工单与对账；DLQ 不是丢弃证据。','Arrival time and second-granularity created do not reconstruct strict business order. If a refund event precedes local capture posting, retain it for association and query authority. Stale intermediate/failure events cannot regress confirmed success. Provider retry windows are finite, so retain recovery scans, durable exceptions, and reconciliation; dead-lettering is not evidence disposal.'))
parts.append('</section>\n<section>'+h('4 · 完整复式分录、状态与通知同提交','4 · Commit complete entries, state, and notification together'))
parts.append(bi('<strong>一份 posting 要有完整借贷分录，不能用一行“已记账”当账本。</strong> 第4组的 T2 包含唯一效果、完整 journal、payment 状态与 payment.paid Outbox。订单慢了只重投通知，不重放渠道命令。','<strong>A posting includes complete debit/credit entries; a single posted marker is not a journal.</strong> T2 in deck 4 contains the unique effect, complete journal, payment state, and payment.paid outbox. Slow orders replay notifications rather than channel commands.'))
parts.append(decks[3])
parts.append(code('capture.pseudo','Pseudocode · one-full-capture posting transaction'))
parts.append(bi('这是平台视角、尚未结算与出款的简化账：收款 10,000 minor units，借 PSP receivable 资产 10,000，贷 merchant payable 负债 10,000。商户资金不是平台收入。科目性质决定方向，借贷差为零只是必要条件；两边同时写错金额仍会平，代码先核真实金额和绑定。'+ref(9),'These simplified platform books precede settlement/payout: captured 10,000 minor units debits the PSP receivable asset and credits the merchant payable liability. Merchant funds are not platform income. Account type determines direction. Zero debit/credit difference is necessary, but equally wrong amounts still balance, so validate amount and binding first. '+ref(9)))
parts.append(bi('appendEntry 是同一关系库连接内的 INSERT。受控 Posting 过程校验至少两条、每个 tx_id 与 currency 借贷相等、科目模板和业务金额匹配，再一次 COMMIT。普通行 CHECK 不能约束跨行 SUM；生产应限制原始 journal DML 权限，统一走过程，或实现可靠的延迟约束。示例的 SQLite 触发器保护历史 UPDATE/DELETE，不能替代完整分录校验。'+ref(6),'appendEntry inserts through the same DB connection. The controlled Posting process checks at least two entries, per-transaction/currency balance, account template, and business amount before COMMIT. Row CHECK cannot enforce cross-row SUM. Production must restrict raw journal DML to this process or implement reliable deferred constraints. SQLite example triggers prohibit historical UPDATE/DELETE; they do not establish complete-entry balance by themselves. '+ref(6)))
parts.append(bi('金额使用带币种的整数最小单位或精确 decimal；十进制字符串先精确验证精度与范围，不经 float。CNY 100.00 是 10,000，JPY 100 是 100；渠道操作还有特例。'+ref(4)+' 平台承担手续费 300 时可另加借费用 300、贷应收 300：净应收 9,700 + 费用 300 = 应付 10,000。费用按自己的对象/类型身份记，净结算与毛收款分别对账。','Use currency-tagged integer minor units or exact decimal. Validate decimal-string precision/range without float. CNY 100.00 is 10,000; JPY 100 is 100, with provider operation exceptions. '+ref(4)+' A platform-borne fee of 300 can append debit expense/credit receivable: net receivable 9,700 plus expense 300 equals payable 10,000. Fees have their own effect identity/type; reconcile net settlement separately from gross capture.'))
parts.append(bi('Order relay 只读已提交 Outbox；订单在自己的事务中去重 event_id、核 pay_no/订单版本与金额并应用状态机，再 ACK。一次完整收款的 payment.paid 可用 paid:pay_no 作稳定事件 ID，退款另用 refunded:refund_id。订单已关则保留真实收款与退款责任，不复活订单。更正追加引用原流水的冲正，退款是外部资金动作，两者不互相冒充。','Order relay reads only committed outbox. Orders deduplicate event_id, validate payment/order version and amount, apply their state machine, then ACK. For one full capture, paid:pay_no is a stable payment.paid event ID; refunds use refunded:refund_id. A closed order retains the real receipt and refund obligation without reopening. Corrections append linked reversals; a refund is an external funds movement, not an interchangeable internal correction.'))
parts.append('</section>\n<section>'+h('5 · 退款先占额度，UNKNOWN 不归还','5 · Reserve refund capacity and retain it during UNKNOWN'))
parts.append(bi('<strong>可退 = captured − refunded − reserved；所有入口锁同一聚合。</strong> 第5组 r0 已退 3,000、r1 预留 2,000，10,000 中还可退 5,000。渠道受理不是成功，超时也不能释放 r1 的额度。','<strong>Available = captured − refunded − reserved; every entry point locks the same aggregate.</strong> In deck 5, r0 refunded 3,000 and r1 reserved 2,000, leaving 5,000 of 10,000. Provider acceptance is not success, and timeout cannot release r1’s capacity.'))
parts.append(decks[4])
parts.append(code('reserve_refund.pseudo','Pseudocode · reserve one keyed refund'))
parts.append(code('refund_result.pseudo','Pseudocode · resolve one refund atomically'))
parts.append(bi('预留事务返回 202 + r1，worker 从已提交命令请求 PSP，并使用 r1 对应的稳定渠道键、冻结金额和原 capture 绑定。收款与退款的 API operation 分开。Stripe 允许同一扣款多次部分退款但累计不超原金额；本地也要挡住两个并发请求同时花掉最后额度。'+ref(5),'Reservation returns 202 + r1. The worker uses committed intent, r1’s stable provider key, frozen amount, and original capture binding. Create/refund API operations have different identity scopes. Stripe allows multiple partial refunds within the original total; enforce the bound locally so concurrent requests cannot spend the same remaining capacity. '+ref(5)))
parts.append(bi('insertPostingUnique 是在同一事务里执行带效果唯一约束的 INSERT，不吞冲突。退款结果必须绑定本地 r1 与外部 refund_id；同一外部退款不能同时结转另一笔本地退款。成功时两条反向分录、reserved 减额、refunded 增额、r1 终态与事件同提交；半份分录或提交失败则全部回滚。重复成功或旧失败不重复结转，矛盾证据持久进 Review。','insertPostingUnique is an INSERT under the effect UNIQUE constraint in the same transaction, without swallowing conflicts. Bind local r1 to its external refund_id; one external refund cannot settle two local reservations. Success commits both reverse entries, reservation decrement, refunded increment, terminal state, and event together. Partial journal or failed commit rolls back all of them. Duplicate success/stale failure never converts capacity twice; retain contradictory evidence in Review.'))
parts.append(bi('UNKNOWN/处理中保留预留，明确“未退款且不会再执行”才释放一次。串行退款队列可降锁竞争，但重投、人工入口与多实例仍要经过数据库额度约束。例子的借商户应付、贷 PSP 应收限定 PSP 尚未结算、商户尚未出款、平台承担费且忽略费返还；已结算要换现金/清算科目，已出款还涉及回收资金。','UNKNOWN/pending retains reservation; release once only after proof of no refund and no future execution. A per-payment queue may reduce contention, but redelivery/manual/multi-instance entry still requires DB bounds. Debit merchant payable/credit PSP receivable assumes no PSP settlement, no merchant payout, platform-borne fees, and no fee reimbursement. Settled funds need cash/clearing accounts; payouts add recovery obligations.'))
parts.append('</section>\n<section>'+h('6 · 对账修账与知识，不再扣一次','6 · Reconcile books and knowledge without charging again'))
parts.append(bi('<strong>固定外部批次与内部快照，按对象比较，再用原效果键修复。</strong> 第6组 Repair 的成功回程等 Payment DB 提交；工单是否关掉不能决定钱再发生一次。','<strong>Fix the external batch and internal snapshot, compare by object, and repair with the original effect key.</strong> Deck 6 waits for Payment DB commit before acknowledging repair; an open case is never permission to move money twice.'))
parts.append(decks[5])
parts.append(code('reconcile.pseudo','Pseudocode · repeatable evidence-driven reconciliation'))
parts.append(bi('Normalizer 保留 batch_id、文件哈希/版本、原行、时区与结算区间；Adyen 的 Settlement details report 面向已结算付款与交易费用，不能视作当天所有受理请求的最终清单。'+ref(7)+' 内部 W 必须标识可重现的一致快照/保留的数据集，不能随便取 max(id) 当提交水位：并发事务可能先拿 ID 后提交。','Normalizer retains batch ID, file hash/revision, raw rows, timezone, and settlement interval. Adyen’s Settlement details report covers settled payments and transaction costs, not every accepted request for that calendar day. '+ref(7)+' Internal W must identify a reproducible consistent snapshot or retained dataset; max(id) is not automatically a commit watermark because concurrent transactions can allocate IDs before committing.'))
parts.append(table([('差异','Difference'),('先查什么','Investigation'),('允许的动作','Permitted action')],[
[('外部有、内部无','External only'),('权威对象、账户/绑定、金额/币种、原动作','Authoritative object, account/binding, amount/currency, original operation'),('满足证据条件走同一 Posting；缺本地退款关联先 Review','Use the same Posting gate; review a missing local refund association')],
[('内部有、外部无','Internal only'),('报告完整性、在途/迟到、修订、同一切点','Report completeness, in-flight/late rows, revisions, matching cutoffs'),('继续查询/滚动复核，不凭缺行冲正','Query/revisit; do not reverse merely because a row is absent')],
[('双方都有但不一致','Both present but differ'),('身份、数量、gross/fee/net 与币种','Identity, count, gross/fee/net, currency'),('留证据与工单；更正须独立授权/引用','Retain evidence/case; corrections need separate authority/reference')]]))
parts.append(bi('先检查 journal 自身平衡，再检查 payment/refund 聚合与对应分录，最后核外部同范围记录。总金额相等可能是错单抵消，故身份和笔数也比较。报告修正版追加证据，批次完整性验证后才能推进外部水位；迟到跨日放滚动窗，固定 T+1 不是完整性的证明。实时查询缩短未知窗口，结算报告补齐覆盖面，两者不能互相替代。','First check journal balance, then payment/refund aggregates against their entries, then external records at matching scope. Equal totals can hide offsetting wrong operations, so compare identity and count too. Append report revisions and advance external watermarks only after verifying completeness. Revisit late cross-day records; T+1 does not prove completeness. Live queries reduce uncertainty sooner, while reports expand coverage; neither replaces the other.'))
parts.append('</section>\n<section>'+h('复盘：每个崩溃点都能指回持久记录','Recap: name the durable record at each crash'))
parts.append(table([('反例','Counterexample'),('恢复依据','Recovery record/constraint')],[
[('202 回包丢失，用户换 header','Acceptance reply lost; header changed'),('请求键 + 业务意图 UNIQUE 返回原 pay_no','Request/business-intent UNIQUE resolves the original pay_no')],
[('PSP 已执行，worker 超时或崩溃','Provider executed; worker timed out/crashed'),('原 a7、固定期限与对象证据；UNKNOWN 不换渠道','Original a7, fixed window, object evidence; UNKNOWN never switches providers')],
[('两个不同 event 都说 c9 成功','Two events report successful c9'),('接收键各自保留，金额效果 UNIQUE 只入一次','Keep both receipt identities; effect UNIQUE posts once')],
[('只写第一条分录后断电','Crash after the first journal entry'),('整个 T2 回滚；没有半本账、paid 状态或通知','T2 rolls back: no partial journal, paid state, or event')],
[('r1 未决，同时申请剩余额度','r1 unresolved while another refund requests capacity'),('同付款锁与 reserved/refunded 约束','Payment lock and reserved/refunded bounds')],
[('补账提交后工单未关闭就崩溃','Repair committed but case closure crashed'),('重跑原 posting_key，读原结果后关闭工单','Rerun original posting_key, read result, then close case')]]))
parts.append(bi('面试主线：先保存 payment/a7/命令，承认渠道结果未知；inbox 先接管，再以业务效果入完整账；账与通知同提交，订单自己的幂等另做；退款先预留，未知不释放；对账固定范围，以原键修复。新增部分 capture 时，每次 capture 独立键并锁累计限额；授权成功不等于捕获成功。','Interview narrative: persist payment/a7/command, retain channel uncertainty, durably receive inbox events, post complete business effects, atomically preserve notification intent, let orders deduplicate locally, reserve refunds, and reconcile fixed scopes through original keys. Partial capture adds independent capture keys and a locked cumulative bound; authorization alone is not capture.'))
parts.append(bi('同源示例：<a href="../examples/ch24/README.md">运行说明与依赖契约</a>、<a href="../examples/ch24/schema.sql">完整 SQLite 教学 schema</a>、<a href="../examples/ch24/model.py">事务/故障契约模型</a>。页面伪代码不伪装成可编译 Java；SQLite 检查验证本地原子与约束，不证明真实 PSP、网络时限、PostgreSQL 切主或生产吞吐。','Shared-source examples: <a href="../examples/ch24/README.md">run instructions and contracts</a>, <a href="../examples/ch24/schema.sql">complete SQLite teaching schema</a>, and <a href="../examples/ch24/model.py">transaction/failure contract model</a>. Page pseudocode is not compilable Java. SQLite checks cover local atomicity/constraints, not a live PSP, network bounds, PostgreSQL failover, or production throughput.'))
parts.append('</section>\n<section>'+h('引用与适用范围','References and applicability'))
refs=[
(1,'Stripe · Idempotent requests','API v1 首次响应缓存、参数比较与键保留；不外推 v2。','API v1 first-response replay, parameter comparison, and retention; not a v2 rule.'),
(2,'Stripe · Advanced error handling','API v1 24 h 内重试与 indeterminate 500；超窗核实，不换键逃逸。','API v1 retry window and indeterminate 500; resolve after expiry rather than changing keys.'),
(3,'Stripe · Webhooks','原始 body 验签、异步、重复与乱序；inbox 是本章选择。','Raw-body verification, async, duplicates, and ordering; inbox is this chapter’s design.'),
(4,'Stripe · Supported currencies','最小单位、JPY 与按操作的币种特例。','Minor units, JPY, and operation-specific currency exceptions.'),
(5,'Stripe · Refund and cancel payments','多次部分退款上限与 pending/failed；本地预留为设计推导。','Partial-refund limits and pending/failed outcomes; local reservations are our design.'),
(6,'PostgreSQL 18 · Constraints','非空、唯一与行级 CHECK 的跨行限制。','Non-null/unique constraints and the cross-row limits of CHECK.'),
(7,'Adyen · Settlement details report','已结算交易、费用及交易级对账；批次水位方案为推导。','Settled transactions, costs, and transaction-level reconciliation; watermark policy is derived.'),
(8,'AWS · Transactional outbox pattern','本地双写窗口与重复投递；不把渠道纳入数据库事务。','Local dual-write failure windows and duplicates; provider effects remain outside the DB transaction.'),
(9,'TigerBeetle · Financial accounting','会计视角与科目借贷方向；不引入该数据库。','Accounting perspective and debit/credit roles; no adoption of that database.'),
(10,'PostgreSQL 18 · WAL configuration','同步提交与副本持久边界；切主策略仍需设计。','Synchronous commit and standby durability; promotion policy still needs a design.')]
parts.append('<ol class="references">'+''.join('<li id="ref-'+str(n)+'"><a href="'+urls[n]+'" target="_blank" rel="noopener">'+title+'</a>'+bi(z,e)+'</li>' for n,title,z,e in refs)+'</ol>')
parts.append(bi('以上一手资料于 2026-10-23 重新核验。数值、inbox/预留/水位与恢复策略是本章教学设计；产品行为只在所标 API/版本范围内引用。站内延伸：<a href="ch18.html">Ch18</a>、<a href="ch25.html">Ch25</a>、<a href="ch41.html">Ch41</a>。','Primary sources rechecked on 2026-10-23. Numbers, inbox/reservation/watermark choices, and recovery policies are teaching design. Product behavior is cited only for the marked API/version. Continue with <a href="ch18.html">Ch18</a>, <a href="ch25.html">Ch25</a>, and <a href="ch41.html">Ch41</a>.'))
parts.append('</section>\n<section>'+h('闪卡','Flashcards'))
questions=[
('为什么换 header 不能变成新付款？','Why does a new header not create a new payment?','请求键挡重投；environment+商户+订单+授权业务版本另有意图 UNIQUE，仍回原 pay_no。','Request identity deduplicates retries; environment/merchant/order/authorized-version intent UNIQUE still resolves pay_no.'),
('T1 与 T2 各提交什么？','What commits in T1 and T2?','T1：payment、attempt、渠道命令；T2：完整借贷分录、效果键、状态与订单事件。PSP 不在其中。','T1: payment, attempt, channel command. T2: complete entries, effect key, state, order event. PSP is outside both.'),
('SENT 已经说明渠道收到了吗？','Does SENT prove provider receipt?','没有。在 I/O 前持久标记“可能送出”，随后崩溃也保留恢复入口。','No. It is persisted before I/O to mean may leave and retain a crash recovery path.'),
('回调先确认了，旧超时还能写 UNKNOWN 吗？','Can a stale timeout overwrite confirmed evidence?','不能。锁内比较终态，仅更新仍未决尝试；不按回包到达时间盲写。','No. Compare terminal state under lock and update only unresolved attempts, not by arrival order.'),
('Stripe 24 h 与缓存 500 适用于哪里？','Where do the Stripe 24 h/cached-500 rules apply?','本章仅指 API v1；超窗未知转查询/核实，不外推 v2，不换新键重扣。','API v1 only here. After unresolved expiry, query/reconcile; do not generalize to v2 or charge with a new key.'),
('本地发送 deadline 能 fence PSP 吗？','Does a local send deadline fence the PSP?','不能排除暂停 worker 或延迟在途请求。须有渠道/时钟/传输边界；否则查原对象或 Review。','It cannot exclude a suspended sender or delayed request. Require provider/clock/transport bounds or query/review.'),
('Webhook 什么时候 ACK？','When should a webhook ACK?','原始 body 验签、核账户后持久 inbox 提交再 2xx；承诺接管，不承诺已入账。','After raw-body verification, account validation, and durable inbox commit; ACK means ownership, not posting.'),
('event_id 与 posting_key 有何区别？','How do event_id and posting_key differ?','前者去重交付；后者按环境/渠道/账户/金额对象/kind 去重效果；退款独立键。','Event ID deduplicates delivery; environment/provider/account/object/kind deduplicates effects; refunds are separate.'),
('借贷平为什么仍可能错？','Why can a balanced journal still be wrong?','两边同错金额或科目仍平。先核绑定与模板，再核支付聚合、外部身份和 gross/fee/net。','Equally wrong amounts/accounts balance. Validate binding/template, then aggregates and external identity/gross/fee/net.'),
('退款 UNKNOWN 的 2,000 怎么办？','What happens to 2,000 during refund UNKNOWN?','保留预留。10,000−已退3,000−预留2,000=5,000；成功时预留转已退，余量仍5,000。','Keep reserved: 10,000−3,000 refunded−2,000 reserved=5,000. Success converts reserve, leaving 5,000.'),
('对账的 W 可以直接用 max(id) 吗？','Can reconciliation W simply be max(id)?','不能默认。ID 分配可能早于提交；W 要标识可重现一致快照或保留数据集。','Not by default: IDs may be allocated before commit. W must identify a reproducible snapshot or retained dataset.'),
('补账后工单没关又重跑怎么办？','What if repair reruns before case closure?','用原业务效果键读原入账结果，确认提交后关工单；绝不再扣款。','Reuse the original effect key, resolve the committed posting, then close the case; never charge again.'),
('十分钟回调积压多久消化？','How long to drain a ten-minute receipt backlog?','162×600=97,200；净500−162=338/s；约288秒，前提是DB仍承受该混合负载。','162×600=97,200; spare500−162=338/s; about288s if the DB sustains that mixed load.'),
('年度 978.2 GB 是总盘量吗？','Is annual 978.2 GB total disk?','不是。仅365 GB支付+102.2 GB分录+511 GB投递审计；三份2.9346 TB，索引/WAL/退款等另算。','No. Only365 GB payments+102.2 GB entries+511 GB audits; three copies2.9346 TB, excluding indexes/WAL/refunds.')]
parts.append('<p class="cite">'+lang('点一下翻面，回答时指出持久记录与边界。','Click to flip; name the durable record and boundary.')+'</p><div class="cards-grid">'+''.join('<button type="button" class="flip"><span class="q">'+lang(zq,eq)+'</span><span class="a">'+lang(za,ea)+'</span></button>' for zq,eq,za,ea in questions)+'</div></section>\n')
